const TARGET_SIZE = env.get("TARGET_SIZE");
const items = msg.metadata.files.items;
const utils = global.get("utils");
const tmpDir = os.tmpdir();
const kept = [];

for (const file of items) {
    const buffer = global.get("files." + file.context_key);

    if (!buffer || buffer.length === 0) {
        kept.push(file);
        continue;
    }

    if (buffer.length <= TARGET_SIZE) {
        kept.push(file);
        continue;
    }

    if (!utils.is_compressible(file.type)) {
        kept.push(file);
        continue;
    }

    const isVideo = file.type.startsWith('video/');
    const isAudio = file.type.startsWith('audio/');
    const isImage = file.type.startsWith('image/');

    // --- IMAGE: compress with sharp ---
    if (isImage) {
        try {
            let quality = 80;
            let compressed = await sharp(buffer).rotate().jpeg({ quality }).toBuffer();

            while (compressed.length > TARGET_SIZE && quality > 10) {
                quality -= 10;
                compressed = await sharp(buffer).rotate().jpeg({ quality }).toBuffer();
            }

            if (compressed.length <= TARGET_SIZE) {
                global.set("files." + file.context_key, compressed);
                file.name = file.name.replace(/\.[^.]+$/, '') + '.jpg';
                file.type = 'image/jpeg';
                file.size = compressed.length;
                node.warn('[SHARP] ' + file.name + ': ' + buffer.length + ' → ' + compressed.length + ' bytes (quality: ' + quality + ')');
                kept.push(file);
            } else {
                node.warn('[SHARP] Could not compress ' + file.name + ' under target');
                msg.metadata.files.failed.push({ name: file.name, reason: utils.FILE_REASONS.COMPRESS_FAILED });
            }
        } catch (e) {
            node.warn('[SHARP] Error: ' + e.message);
            msg.metadata.files.failed.push({ name: file.name, reason: utils.FILE_REASONS.COMPRESS_FAILED });
        }
        continue;
    }

    // --- VIDEO/AUDIO: compress with ffmpeg ---
    const ts = Date.now();
    const inputPath = path.join(tmpDir, 'parat_in_' + ts + '_' + file.name);
    const outputExt = isVideo ? '.mp4' : '.aac';
    const outputPath = path.join(tmpDir, 'parat_out_' + ts + outputExt);

    fs.writeFileSync(inputPath, buffer);

    try {
        const duration = await new Promise((res, rej) => {
            childProcess.execFile('ffprobe', [
                '-v', 'error',
                '-show_entries', 'format=duration',
                '-of', 'default=noprint_wrappers=1:nokey=1',
                inputPath
            ], { timeout: 15000 }, (err, stdout) => {
                if (err) return rej(err);
                const d = parseFloat(stdout);
                if (isNaN(d) || d <= 0) return rej(new Error('Invalid duration: ' + stdout));
                res(d);
            });
        });

        const targetBytes = TARGET_SIZE - (32 * 1024);
        const audioBitrate = 64000;
        const totalBitrate = Math.floor((targetBytes * 8) / duration);
        const videoBitrate = Math.max(totalBitrate - audioBitrate, 50000);

        const args = ['-i', inputPath, '-y'];

        if (isVideo) {
            args.push(
                '-vcodec', 'libx264',
                '-b:v', videoBitrate + '',
                '-maxrate', videoBitrate + '',
                '-bufsize', Math.floor(videoBitrate / 2) + '',
                '-preset', 'fast',
                '-vf', 'scale=min(640\\,iw):min(480\\,ih):force_original_aspect_ratio=decrease,scale=trunc(iw/2)*2:trunc(ih/2)*2',
                '-acodec', 'aac',
                '-b:a', '64k',
                '-movflags', '+faststart'
            );
        } else {
            const audioBr = Math.min(Math.floor(totalBitrate), 128000);
            args.push('-acodec', 'aac', '-b:a', audioBr + '');
        }

        args.push(outputPath);

        const compressed = await new Promise((res, rej) => {
            childProcess.execFile('ffmpeg', args, { timeout: 120000 }, (error) => {
                if (error) return rej(error);
                res(fs.readFileSync(outputPath));
            });
        });

        node.warn('[FFMPEG] ' + file.name + ': ' + buffer.length + ' → ' + compressed.length + ' bytes (duration: ' + duration.toFixed(1) + 's)');

        global.set("files." + file.context_key, compressed);
        if (isVideo) {
            file.name = file.name.replace(/\.[^.]+$/, '') + '.mp4';
            file.type = 'video/mp4';
        }
        file.size = compressed.length;
        kept.push(file);

        fs.unlinkSync(inputPath);
        fs.unlinkSync(outputPath);
    } catch (e) {
        node.warn('[FFMPEG] Failed for ' + file.name + ': ' + e.message);
        try { fs.unlinkSync(inputPath); } catch (err) { }
        try { fs.unlinkSync(outputPath); } catch (err) { }
        msg.metadata.files.failed.push({ name: file.name, reason: utils.FILE_REASONS.COMPRESS_FAILED });
    }
}

msg.metadata.files.items = kept;
return msg;
